{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Menaquinone-4, a polyprenyl quinone closely related to the query's ubiquinone/polyprenyl architecture, had an absolute oral bioavailability of only 13.5% in dogs (soft-capsule, non-fasted), providing direct threshold-relevant evidence for F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Oral absorption of menaquinone-4 was almost absent without bile in rats, demonstrating that this lipophilic quinone class depends on bile/micelle formation for absorption; the query's much larger decaprenyl quinone is expected to face the same or greater solubility-limited absorption barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Plain menaquinone-4 had very low oral AUC in fasted beagle dogs, and a DM-β-CyD complex raised Cmax 17-fold and AUC 19-fold, showing that the intrinsic bioavailability of the unformulated polyprenyl quinone is poor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol, which combines a polar chromanol head with an isoprenoid tail, has poor oral bioavailability in humans; this polar-head/long-lipophilic-tail architecture is the closest human structural parallel to the query's quinone/polyprenyl structure and supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Lycopene, a large C40 polyisoprenoid, showed only about 1.2% systemic availability after oral dosing in humans, demonstrating that very large, highly lipophilic polyisoprenoids can have F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a smaller C40 polyisoprenoid hydrocarbon, showed 58.5% absolute bioavailability in humans, indicating that high lipophilicity alone does not always cause low F; however, its lower molecular weight and lack of a polar quinone head limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "MK-7 was reported to have superior bioavailability relative to vitamin K1 due to its extended isoprenoid chain, slower clearance, and higher systemic retention; this relative comparison could suggest that longer polyprenyl chains improve systemic exposure, but it does not establish an absolute F ≥ 20% for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is coenzyme Q10, a very large, highly lipophilic decaprenyl quinone. The closest high-similarity experimental evidence—menaquinone-4 absolute F of 13.5% in dogs, its bile-dependent and formulation-sensitive absorption, and tocotrienol's poor human bioavailability—supports F < 20%. Counterexamples (phytoene 58.5%, MK-7 relative superiority) are less transferable or not threshold-relevant. Physicochemical liabilities (MW ~863, extreme lipophilicity, no ionizable groups) reinforce low oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for coenzyme Q10 itself in the provided evidence.",
    "The closest absolute F value (MK-4, 13.5%) is from dogs, not humans; human absolute F for menaquinones is not provided.",
    "Formulation, fed/fasted state, and dose for the query are unspecified; these strongly modulate absorption of lipophilic quinones.",
    "Conflicting results among polyisoprenoids (phytoene high vs lycopene low) create uncertainty in extrapolation."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C28", "C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "menaquinone-4 oral absorption"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C27"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "menaquinone-7 relative bioavailability"
    }
  ],
  "revision_action": "strengthen"
}

